package io.github.hienpham0344.stayfinder.notification.controller;
import io.github.hienpham0344.stayfinder.notification.service.NotificationService;import io.github.hienpham0344.stayfinder.notification.dto.*;import io.github.hienpham0344.stayfinder.common.response.ApiResponse;import io.github.hienpham0344.stayfinder.common.exception.*;import io.github.hienpham0344.stayfinder.security.CurrentUser;import org.springframework.web.bind.annotation.*;import org.springframework.http.ResponseEntity;import org.springframework.data.domain.*;import jakarta.validation.Valid;import java.util.*;
@RestController @RequestMapping("/api/notifications")public class NotificationController{
 private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}
 @GetMapping public ResponseEntity<ApiResponse<NotificationPage>> list(@RequestParam(defaultValue="false")boolean unread,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100)throw new BusinessException(ErrorCode.VALIDATION_ERROR);return ResponseEntity.ok(ApiResponse.success(service.list(CurrentUser.require().id(),unread,PageRequest.of(page,size,Sort.by(Sort.Order.desc("createdAt"),Sort.Order.desc("id"))))));}
 @GetMapping("/unread-count")public ResponseEntity<ApiResponse<Map<String,Long>>> count(){return ResponseEntity.ok(ApiResponse.success(Map.of("count",service.unreadCount(CurrentUser.require().id()))));}
 @PatchMapping("/{id}")public ResponseEntity<ApiResponse<NotificationResponse>> read(@PathVariable UUID id,@Valid @RequestBody NotificationReadRequest request){return ResponseEntity.ok(ApiResponse.success(service.markRead(CurrentUser.require().id(),id)));}
 @PostMapping("/read-all")public ResponseEntity<ApiResponse<NotificationReadAllResponse>> all(@Valid @RequestBody NotificationReadAllRequest request){return ResponseEntity.ok(ApiResponse.success(service.markAllRead(CurrentUser.require().id(),request.snapshotTime())));}
}
